style.css:
@-moz-document domain("roblox.com") {
/* 1. ARKA PLAN RESMİ */
    body, .content, .container-main, .main-layout {
        background: url("https://cdn.discordapp.com/attachments/1261100725228933203/1535063351535739042/image.png?ex=6a7666a7&is=6a751527&hm=e418cf0a21b54ad9107a10f70e6b9a1c49190da6afa7c1880ded8043a0b57fda&") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. PANEL VE KUTULARI YARI SAYDAM YAPMA (CAM EFEKTİ) */
    .section-content, 
    .gandalf-roblox-pc-container, 
    .game-card-container, 
    .places-list-container,
    .avatar-card-container,
    .item-card-container,
    .layer, 
    .well {
        background: rgba(20, 20, 20, 0.6) !important; /* Son rakam (0.6) saydamlıktır */
        backdrop-filter: blur(10px) !important; /* Arkadaki resmi flulaştırır */
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        border-radius: 12px !important;
    }

    /* 3. ÜST SİYAH MENÜ BARI */
    #header {
        background: rgba(15, 15, 15, 0.85) !important;
        backdrop-filter: blur(5px) !important;
    }

    /* 4. SOLDAKİ AÇILIR MENÜ */
    #navigation {
        background: rgba(20, 20, 20, 0.9) !important;
    }

    /* REKLAMLARI GİZLEME */
    #AdvertisingLeaderboard, .abp, .ad-annotations, #RightRailBar {
        display: none !important;
    }
}
